import re

content = open('/home/user/JSS-2026-Example/software/mcfm/src/Mods/pp_mod.f90').read()
start = content.index('reshape((/') + len('reshape((/')
end = content.index('/) &\n    , (/ 9,9,9,9 /))')
data_str = content[start:end]
nums = re.findall(r'\d+', data_str)
assert len(nums) == 6561, f"Expected 6561, got {len(nums)}"

# Format as C++ array initializer, 27 per line (matching Fortran source layout)
lines = []
for i in range(0, len(nums), 27):
    chunk = nums[i:i+27]
    lines.append('    ' + ', '.join(chunk))
array_body = ',\n'.join(lines)

cpp_code = f'''#include <pp_mod.hpp>
#include <algorithm>

namespace pp_mod {{

  // Flat initializer data for pp(-4:4,-4:4,-4:4,-4:4).
  // Layout is column-major (Fortran storage order): first index varies fastest.
  // 9*9*9*9 = 6561 elements, taken directly from the Fortran reshape literal.
  static const int pp_init[6561] = {{
{array_body}
  }};

  // pp(-4:4,-4:4,-4:4,-4:4): 9x9x9x9 column-major 4D integer array.
  // start indices set to -4 so that operator()(i,j,k,l) with i,j,k,l in [-4,4]
  // maps to the correct flat offset matching the Fortran original.
  FArray4D<int> pp(9, 9, 9, 9, -4, -4, -4, -4);

  // Copy the static initializer data into pp.data at program startup.
  // This runs after pp is constructed (C++ guarantees intra-TU order).
  struct PPDataInit {{
    PPDataInit() {{
      std::copy(pp_init, pp_init + 6561, pp.data);
    }}
  }};
  static PPDataInit _pp_data_init;

}} // namespace pp_mod

extern "C" {{
  int* pp_mod_pp() {{
    return pp_mod::pp.data; // @coverage-probe
  }}
}}
'''

with open('/home/user/JSS-2026-Example/software/mcfm/src/Mods/pp_mod.cpp', 'w') as f:
    f.write(cpp_code)
print("Written pp_mod.cpp")
PYEOF
